import { test, expect } from "@playwright/test"
import { FieldValue } from "firebase-admin/firestore"
import { readFileSync } from "fs"
import path from "path"
import { fileURLToPath } from "url"
import {
  clearCollections,
  fakeNfcTap,
  getAdminFirestore,
  getCheckoutDocs,
  installFakeKioskBridge,
  KIOSK_DESKTOP_ONLY,
} from "./helpers"
import { NFC_TAG_UID, NFC_TAG_UID_2, NFC_USER_ID } from "./global-setup"

const __dirname = path.dirname(fileURLToPath(import.meta.url))

/** Read picc+cmac generated by global-setup.ts */
function readE2eData(): {
  picc: string
  cmac: string
  picc2: string
  cmac2: string
  authUid: string
} {
  const dataPath = path.resolve(__dirname, ".e2e-data.json")
  return JSON.parse(readFileSync(dataPath, "utf-8"))
}

test.beforeEach(async () => {
  await clearCollections("checkouts")
  // The seeded piccs encode counter=0; the SDM replay defense rejects a
  // second tap with the same counter. Each browser project re-runs the
  // suite, so without this reset the second project trips the defense.
  const db = getAdminFirestore()
  await Promise.all(
    [NFC_TAG_UID, NFC_TAG_UID_2].map((uid) =>
      db
        .collection("tokens")
        .doc(uid)
        .update({ lastSdmCounter: FieldValue.delete() }),
    ),
  )
})

test.describe("NFC tag checkout", () => {
  test("tag-identified user — full E2E through Functions emulator", async ({
    page,
  }) => {
    const { picc, cmac } = readE2eData()

    // Navigate to the wizard's canonical tag entry, /checkin?picc=…&cmac=…
    // (the refactor reserves "/" for typed entries; the kiosk lands on
    // /checkin directly). Going via the "/" dispatcher would verify the tag
    // there AND again in the wizard — the second tap of the same SDM counter
    // trips the replay defense (verify_tag.ts) and falls back to anon check-in.
    await page.goto(`/checkin?picc=${picc}&cmac=${cmac}`)

    // ── No landing page — tag identifies the user directly ──
    // Wait for tag verification to complete and person to be pre-filled
    // Name is split into Vorname="NFC" and Nachname="Tester"
    await expect(page.getByText("nfc@test.com")).toBeVisible({
      timeout: 15_000,
    })

    // "Weiter" should be enabled (pre-filled user)
    await expect(
      page.getByRole("button", { name: "Weiter" }),
    ).toBeEnabled()

    // No terms checkbox for pre-filled users
    await expect(page.locator("#terms-accept")).not.toBeVisible()

    // ── Proceed through checkout ──
    await page.getByRole("button", { name: "Weiter" }).click()
    await expect(page.getByText("Werkstätten wählen")).toBeVisible()

    await page.getByRole("button", { name: "Zum Checkout" }).click()
    await expect(page.getByText("Dein Besuch")).toBeVisible()

    // Issue #414: the seeded NFC user is a Vereinsmitglied, so the
    // Sammelrechnung (monthly-bill) card must be offered even though the
    // tag-tap principal has no client-side user doc. Before the fix it was
    // gated on `identifiedUserDoc?.activeMembership` (null for a tag tap)
    // and the member only ever saw QR-Rechnung + TWINT.
    await page.getByTestId("payment-option-monthly").click()

    // ── Step 4: commit; the server accepts it for the member (#750) ──
    await page.getByRole("button", { name: "Auf Sammelrechnung setzen" }).click()
    await expect(page.getByTestId("payment-confirmation")).toBeVisible({
      timeout: 30_000,
    })

    // ── Verify Firestore ──
    const checkouts = await getCheckoutDocs()
    expect(checkouts.length).toBeGreaterThanOrEqual(1)

    const checkout = checkouts[0] as Record<string, unknown>
    expect(checkout.status).toBe("closed")
    expect(checkout.paymentMethod).toBe("monthly")

    // userId should reference the NFC user
    const userIdRef = checkout.userId as { path: string }
    expect(userIdRef.path).toBe(`users/${NFC_USER_ID}`)
  })

  test("switching badge re-prefills the new user — no stuck state (#420)", async ({
    page,
  }) => {
    const { picc, cmac, picc2, cmac2 } = readE2eData()

    // First badge: land on the wizard's canonical tag entry. This is exactly
    // what BridgeNfcRouter does for a kiosk tap (navigate to /checkin?picc…).
    await page.goto(`/checkin?picc=${picc}&cmac=${cmac}`)
    await expect(page.getByText("nfc@test.com")).toBeVisible({
      timeout: 15_000,
    })

    // Second badge tapped while the first is already identified. Before the
    // #420 fix the bridge routed through "/" (double-verify), the SDM replay
    // defense rejected the wizard's second verify, and the page got stuck:
    // neither tag- nor anon-identified, no re-prefill. The new identity must
    // now replace the first on the primary card.
    await page.goto(`/checkin?picc=${picc2}&cmac=${cmac2}`)

    // The second user's email replaces the first — the switch took effect.
    await expect(page.getByText("badge2@test.com")).toBeVisible({
      timeout: 15_000,
    })
    await expect(page.getByText("nfc@test.com")).not.toBeVisible()

    // And the wizard is usable, not stuck: the pre-filled user can proceed.
    await expect(
      page.getByRole("button", { name: "Weiter" }),
    ).toBeEnabled()
  })

  // Issue #689: a badge tap over an idle, identified kiosk screen switched
  // principal inside the live page. The wizard's listeners stayed bound to
  // the first member, so the second one saw the first one's data.
  // Unlike the #420 test above this drives the tap through a fake Electron
  // bridge — the in-place path `page.goto` never takes.
  test("bridge tap over an identified session reloads — no roster leak (#689)", async ({
    page,
    isMobile,
  }) => {
    test.skip(isMobile, KIOSK_DESKTOP_ONLY)
    const { picc, cmac, picc2, cmac2 } = readE2eData()
    const db = getAdminFirestore()
    // A is a throwaway user behind the first tag, NOT the seeded NFC user,
    // so nothing this test does can leak into the seeded user's state
    // (issue #691).
    const tokenRef = db.doc(`tokens/${NFC_TAG_UID}`)
    const parentRef = db.doc("users/e2e-switch-family-parent")
    await parentRef.set({
      firstName: "Fami",
      lastName: "Eltern",
      email: "switch-parent@test.com",
      userType: "erwachsen",
      roles: [],
      permissions: [],
      termsAcceptedAt: FieldValue.serverTimestamp(),
      created: FieldValue.serverTimestamp(),
    })
    await tokenRef.update({ userId: parentRef })

    try {
      await installFakeKioskBridge(page)

      await page.goto(`/checkin?kiosk=&picc=${picc}&cmac=${cmac}`)
      await expect(page.getByText("switch-parent@test.com")).toBeVisible({
        timeout: 15_000,
      })

      // B taps without A having touched anything — no dialog (A's
      // "Besuch starten" countdown, if already running, starts A's visit
      // first, issue #732), but the page must be wiped and reloaded.
      await fakeNfcTap(page, picc2, cmac2)

      await expect(page.getByText("badge2@test.com")).toBeVisible({
        timeout: 15_000,
      })
      await expect(page.getByText("switch-parent@test.com")).not.toBeVisible()
      await expect(page.getByRole("alertdialog")).not.toBeVisible()
      expect(
        await page.evaluate(() => sessionStorage.getItem("fakeBridgeResets")),
      ).toBe("1")
    } finally {
      await Promise.all([
        tokenRef.update({ userId: db.doc(`users/${NFC_USER_ID}`) }),
        parentRef.delete(),
      ])
    }
  })

  // Issue #732: after a badge tap at the kiosk "Besuch starten" fills over
  // 5 s and starts the visit on its own; the start screen confirms it.
  test.describe("kiosk auto-start (issue #732)", () => {
    test("tap, wait 5 s: the visit starts and the start screen confirms it", async ({
      page,
      isMobile,
    }) => {
      test.skip(isMobile, KIOSK_DESKTOP_ONLY)
      const { picc, cmac } = readE2eData()
      await installFakeKioskBridge(page)
      await page.goto(`/checkin?kiosk=&picc=${picc}&cmac=${cmac}`)
      await expect(page.getByText("nfc@test.com")).toBeVisible({
        timeout: 15_000,
      })
      await expect(page.getByTestId("checkin-start-visit")).toHaveAttribute(
        "data-countdown",
        "running",
      )

      // No touch: the reset lands on the fresh start screen with the toast.
      await expect(
        page.getByText(
          "Besuch von NFC gestartet. Viel Spass in der Werkstatt!",
        ),
      ).toBeVisible({ timeout: 15_000 })
      await expect(page.getByTestId("checkin-seg-account")).toBeVisible()
      await expect(page).not.toHaveURL(/started=/)

      const open = (await getCheckoutDocs()).filter(
        (c) => (c as Record<string, unknown>).status === "open",
      ) as Record<string, unknown>[]
      expect(open).toHaveLength(1)
      expect(open[0].usageType).toBe("regular")
      expect((open[0].userId as { path: string }).path).toBe(
        `users/${NFC_USER_ID}`,
      )
    })

    test("tap, then 'Person hinzufügen': no auto-start", async ({ page, isMobile }) => {
      test.skip(isMobile, KIOSK_DESKTOP_ONLY)
      const { picc, cmac } = readE2eData()
      await installFakeKioskBridge(page)
      await page.goto(`/checkin?kiosk=&picc=${picc}&cmac=${cmac}`)
      await expect(page.getByTestId("checkin-start-visit")).toHaveAttribute(
        "data-countdown",
        "running",
        { timeout: 15_000 },
      )
      await page.getByRole("button", { name: "Person hinzufügen" }).click()
      await expect(
        page.getByTestId("checkin-start-visit"),
      ).not.toHaveAttribute("data-countdown", "running")

      await page.waitForTimeout(6_000)
      await expect(page.getByText("nfc@test.com")).toBeVisible()
      await expect(
        page.getByRole("button", { name: /Besuch starten/ }),
      ).toBeVisible()
      expect(await getCheckoutDocs()).toHaveLength(0)
    })

    test("tap A, tap B during the countdown: A's visit starts, B sees the confirmation", async ({
      page,
      isMobile,
    }) => {
      test.skip(isMobile, KIOSK_DESKTOP_ONLY)
      const { picc, cmac, picc2, cmac2 } = readE2eData()
      await installFakeKioskBridge(page)
      await page.goto(`/checkin?kiosk=&picc=${picc}&cmac=${cmac}`)
      await expect(page.getByTestId("checkin-start-visit")).toHaveAttribute(
        "data-countdown",
        "running",
        { timeout: 15_000 },
      )

      await fakeNfcTap(page, picc2, cmac2)

      await expect(page.getByText("badge2@test.com")).toBeVisible({
        timeout: 15_000,
      })
      await expect(page.getByText("Besuch von NFC gestartet.")).toBeVisible()
      await expect(page.getByRole("alertdialog")).not.toBeVisible()

      const db = getAdminFirestore()
      const a = await db
        .collection("checkouts")
        .where("userId", "==", db.doc(`users/${NFC_USER_ID}`))
        .where("status", "==", "open")
        .get()
      expect(a.size).toBe(1)
      expect(a.docs[0].get("usageType")).toBe("regular")
    })

    test("tap A, touch, tap B: asks before switching", async ({ page, isMobile }) => {
      test.skip(isMobile, KIOSK_DESKTOP_ONLY)
      const { picc, cmac, picc2, cmac2 } = readE2eData()
      await installFakeKioskBridge(page)
      await page.goto(`/checkin?kiosk=&picc=${picc}&cmac=${cmac}`)
      await expect(page.getByTestId("checkin-start-visit")).toHaveAttribute(
        "data-countdown",
        "running",
        { timeout: 15_000 },
      )
      await page.getByRole("heading", { name: "Deine Angaben" }).click()

      await fakeNfcTap(page, picc2, cmac2)
      const dialog = page.getByRole("alertdialog")
      await expect(dialog).toBeVisible({ timeout: 15_000 })
      await expect(dialog).toContainText("Benutzer wechseln?")
      await expect(dialog).toContainText("NFC hat noch keinen Besuch gestartet.")
      await dialog.getByRole("button", { name: "Abbrechen" }).click()
      await expect(page.getByText("nfc@test.com")).toBeVisible()
      expect(await getCheckoutDocs()).toHaveLength(0)
    })

    test("signed in without the bridge (browser): no countdown, no checkout", async ({
      page,
    }) => {
      const { picc, cmac } = readE2eData()
      await page.goto(`/checkin?kiosk=&picc=${picc}&cmac=${cmac}`)
      await expect(page.getByText("nfc@test.com")).toBeVisible({
        timeout: 15_000,
      })
      const start = page.getByTestId("checkin-start-visit")
      await expect(start).toBeVisible()
      await page.waitForTimeout(6_000)
      await expect(start).not.toHaveAttribute("data-countdown", "running")
      await expect(page.getByText("nfc@test.com")).toBeVisible()
      expect(await getCheckoutDocs()).toHaveLength(0)
    })
  })

  test("kiosk mode — shows NFC hint inline in the account section", async ({ page, isMobile }) => {
    test.skip(isMobile, KIOSK_DESKTOP_ONLY)
    await page.goto("/?kiosk")

    // The account section is the default for an anonymous kiosk visitor:
    // switcher on top, identifier field, and the animated badge affordance
    // in its hero state below the "oder" divider.
    await expect(page.getByTestId("checkin-seg-account")).toBeVisible()
    await expect(page.getByTestId("checkin-identifier")).toBeVisible()
    await expect(page.getByTestId("nfc-affordance")).toHaveAttribute(
      "data-mode",
      "hero",
    )

    // No Google sign-in at the shared terminal.
    await expect(page.getByText("Mit Google anmelden")).not.toBeVisible()
  })
})
